#!/bin/bash\n# setup-tests.sh\n# Setup and run SkillOS E2E tests\n\necho \"🎭 SkillOS E2E Tests - Setup Guide\"\necho \"==================================\"\necho \"\"\n\n# Colors for output\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'\nNC='\\033[0m' # No Color\n\necho -e \"${BLUE}Step 1: Installing dependencies...${NC}\"\nnpm install\n\nif [ $? -eq 0 ]; then\n  echo -e \"${GREEN}✓ Dependencies installed successfully${NC}\"\nelse\n  echo -e \"${RED}✗ Failed to install dependencies${NC}\"\n  exit 1\nfi\n\necho \"\"\necho -e \"${BLUE}Step 2: Verifying test files...${NC}\"\nnpx playwright test --list 2>&1 | head -20\n\necho \"\"\necho -e \"${GREEN}✓ Tests are ready to run!${NC}\"\necho \"\"\necho -e \"${YELLOW}Available commands:${NC}\"\necho -e \"  ${GREEN}npm run test${NC}             - Run all tests (Chromium only)\"\necho -e \"  ${GREEN}npm run test:ui${NC}          - Run tests with UI mode\"\necho -e \"  ${GREEN}npm run test:debug${NC}       - Debug tests step-by-step\"\necho -e \"  ${GREEN}npm run test:headed${NC}      - Run tests with visible browser\"\necho -e \"  ${GREEN}npm run test:watch${NC}       - Watch mode (re-run on file changes)\"\necho -e \"  ${GREEN}npm run test:report${NC}      - Show test report\"\necho \"\"\necho -e \"${YELLOW}Important: Before running tests, ensure:${NC}\"\necho \"  1. Backend is running: cd backend && python -m uvicorn main:app --reload --port 8000\"\necho \"  2. Frontend is running: cd frontend && npm run dev\"\necho \"\"\necho -e \"${BLUE}Test Suite Breakdown:${NC}\"\necho \"  • Registration & Authentication: 2 tests\"\necho \"  • Dashboard Functionality: 3 tests\"\necho \"  • Analytics & Insights: 2 tests\"\necho \"  • Recommendations: 1 test\"\necho \"  • Persona-Based Scenarios (6 personas): 6 tests\"\necho \"  • Complete User Journeys: 1 test\"\necho \"  • Performance Tests: 3 tests\"\necho \"  • Data Validation (50 users): 2 tests\"\necho \"\"\necho -e \"${GREEN}Ready to test! 🚀${NC}\"\n